insert into issue_categories (code, label, description, owner, is_gap, sort) values
  ('DOC', 'Documentation', 'The required plan, permit, certificate or record does not exist, is not approved, or has expired.', 'Contractor EHSS management', true, 0),
  ('IMP', 'Implementation', 'The requirement exists on paper but is not being followed in the field.', 'Site management', true, 1),
  ('PLN', 'Planning', 'The work started without being properly planned, risk-assessed or sequenced.', 'Planning and engineering', true, 2),
  ('TRN', 'Training & competence', 'The people doing the work are not trained, certified or assessed as competent for it.', 'Training function', true, 3),
  ('SUP', 'Supervision', 'There is not enough competent supervision present for the work being done.', 'Contractor leadership', true, 4),
  ('RES', 'Resources', 'Not enough people, equipment, facilities or budget allocated to meet the requirement.', 'Contractor leadership', true, 5),
  ('EQP', 'Equipment & facilities', 'Equipment or facilities are defective, uncertified, poorly maintained or unsuitable for the task.', 'Plant and maintenance', true, 6),
  ('SUB', 'Subcontractor control', 'The gap sits with a subcontractor the main contractor is not adequately controlling.', 'Main contractor', true, 7),
  ('INS', 'Inspection & checks', 'Required inspections, tests, drills or self-audits are not being carried out.', 'Contractor EHSS team', true, 8),
  ('REC', 'Records & reporting', 'It happened but was not logged, reported, escalated or tracked through to closure.', 'Contractor EHSS team', true, 9),
  ('COM', 'Communication', 'Briefings, signage, alerts or language barriers mean the requirement has not reached the workforce.', 'Site management', true, 10),
  ('LED', 'Leadership', 'Management presence, participation or visible commitment to the requirement is missing.', 'Senior management', true, 11),
  ('GOOD', 'Good practice', 'Requirement fully met, with evidence of practice beyond the minimum.', '—', false, 12)
